#!/usr/bin/env node
/**
 * Writes src/vendor/leafletBundle.ts: Leaflet's JS and CSS as strings, so the map picker's WebView
 * can inline them instead of downloading them from a CDN. Re-run after changing the leaflet version:
 *
 *   node apps/mobile/scripts/generate-leaflet-bundle.js
 */
const fs = require('fs');
const path = require('path');

const dist = path.dirname(require.resolve('leaflet/dist/leaflet.js', { paths: [__dirname] }));
const version = require(path.join(dist, '..', 'package.json')).version;
// "</script" inside an inlined script would end it early.
const js = fs.readFileSync(path.join(dist, 'leaflet.js'), 'utf8').replace(/<\/script/gi, '<\\/script');
const css = fs.readFileSync(path.join(dist, 'leaflet.css'), 'utf8');

const out = `// GENERATED by scripts/generate-leaflet-bundle.js from leaflet ${version}. Do not edit by hand.
// Leaflet is BSD-2-Clause licensed (c) Vladimir Agafonkin, Cloud​Made.
export const LEAFLET_VERSION = ${JSON.stringify(version)};
export const LEAFLET_JS = ${JSON.stringify(js)};
export const LEAFLET_CSS = ${JSON.stringify(css)};
`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'vendor', 'leafletBundle.ts'), out);
console.log(`Wrote leafletBundle.ts (leaflet ${version}, ${Math.round((js.length + css.length) / 1024)} KB)`);
